const a='AGENTS.md';fs.writeFileSync(a,'## G03横穿入场修复完成 · 2026-10-23\n\n- 整编队按身体半径与后边界平移，三族16/30/32/48/64人合法入场、移动、撤离和冻结返回通过；原五短复现无越界，现行规则两条及隔离旧英雄规则一条均完成18关＋无尽6分钟并结算，其中后两条实际通过横穿，账本零差额。\n- 3生产文件、1新测试共16项；首版60相关专项、最终2288完整回归、类型/数据通过。旧虫族零战损错误断言保留，正式断言逐员计逃出/战死。Current、镜头/输入保持，未构建/发布/提交/推送；非人类/GPU/FPS验收。\n- G03-CROSSING-ENTRY-001及G03-CROSSING-EXIT-002关闭；G03四档装备验证进行中，数值调整仍先讨论。记录docs/project/G03_CROSSING_FIX_20261023.md、reports/qa/g03-crossing-20261023.json。\n\n'+fs.readFileSync(a,'utf8'));console.log(JSON.stringify({revision:b.revision,source:report.source,rows:rows.map(r=>({id:r.summary.id,crossings:r.crossings}))}));
